module protocol::debt;

use protocol::error;
use math::float::Decimal;

public struct Debt has copy, drop, store {
    amount: Decimal,
    borrow_index: Decimal,
}

public(package) fun new(
    amount: Decimal,
    borrow_index: Decimal,
): Debt {
    Debt { amount, borrow_index }
}

public(package) fun has_debt(self: &Debt): bool {
    !self.amount.is_zero()
}

public(package) fun debt(self: &Debt, borrow_index: Decimal): Decimal {
    // avoid any math operation
    if (borrow_index.eq(self.borrow_index)) { return self.amount };
    self.amount.mul(borrow_index).div(self.borrow_index)
}

/// This operation is unsafe because debt might not be up to date with latest market, accrue_interest first
public(package) fun unsafe_debt_amount(self: &Debt): Decimal {
    self.amount
}

/// The debt is cleared
public(package) fun cleared(self: &mut Debt) {
    self.amount = math::float::zero();
}

/// This operation is unsafe because debt might not be up to date with latest market, accrue_interest first
public(package) fun unsafe_decrease(self: &mut Debt, amount: Decimal) {
    self.amount = self.amount.sub(amount);
}

/// This operation is unsafe because debt might not be up to date with latest market, accrue_interest first
public(package) fun unsafe_increase(self: &mut Debt, amount: Decimal) {
    self.amount = self.amount.add(amount);
}

/// Accrue the interest, returns the interest changed
public(package) fun accrue_interest(self: &mut Debt, new_borrow_index: Decimal) {
    assert!(self.borrow_index.le(new_borrow_index), error::invariant_borrow_index_incremental());

    // // If the borrow index hasn't changed, there is no interest to accrue.
    if (self.borrow_index.eq(new_borrow_index)) return;

    self.amount = self.debt(new_borrow_index);
    self.borrow_index = new_borrow_index;
}

public(package) fun borrow_index(self: &Debt): &Decimal {
    &self.borrow_index
}

#[test_only]
public fun snapshot(self: &Debt): (Decimal, Decimal) {
    (self.amount, self.borrow_index)
}

